pick as (select id from pp_pools where ai_description is not null order by md5(id::text || 'final50') limit 15),
src as (
  select 'p.desc' col, p.id rid, 0 ent, p.ai_description x from pp_pools p where p.id in (select id from pick)
  union all select 'p.faq', p.id, o::int, e->>'a' from pp_pools p, jsonb_array_elements(p.ai_faqs) with ordinality a(e,o) where jsonb_typeof(p.ai_faqs) = 'array' and p.id in (select id from pick)
  union all select 'p.tip', p.id, o::int, e from pp_pools p, jsonb_array_elements_text(p.ai_tips) with ordinality a(e,o) where jsonb_typeof(p.ai_tips) = 'array' and p.id in (select id from pick)),
sp as (select src.col, src.rid, src.ent, t.k::int k, replace(t.z, '§', '.') s from src, rx, regexp_split_to_table(regexp_replace(src.x, rx.abbrev, '\1' || '§', 'g'), rx.split) with ordinality t(z, k) where t.z <> ''),
m as (select sp.*, regexp_replace(sp.s, rx.roman, '\1 _', 'g') ms from sp, rx),
k as (select m.*,
    case when ms ~ rx.sing then 'singular' when (ms ~ rx.plur or ms ~ rx.loc) and ms ~ rx.site then null when ms ~ rx.plur then 'plural' when ms ~ rx.loc then 'local' end kind,
    regexp_replace(s, rx.nmask, 'X', 'g') ~ rx.num has_num, s ~ rx.url has_url, (s ~ rx.clause or (s ~ rx.splice and s !~ rx.splice_ok)) has_clause, s ~ rx.polar is_polar, s ~ rx.lex has_lex, s ~ rx.lexps has_lexps, s ~ rx.ins has_ins,
    s ~ rx.gap is_gap, s ~ rx.advice is_adv, s ~ rx.founder is_founder from m, rx),
d as (select k.*, case when kind is null then null when has_ins then 'insurance'
         when kind = 'singular' and is_founder then (case when has_lex or has_lexps then 'fact_vocabulary' when is_polar then 'answer_polarity' end)
         when kind = 'local' and col like 'p.%' then 'local_marker_on_pool_page'
         when has_num then 'number' when has_url then 'url_or_contact' when has_clause then 'second_clause' when is_polar then 'answer_polarity'
         when not is_gap and has_lex then 'fact_vocabulary' when not is_gap and not is_adv and has_lexps then 'fact_vocabulary' end why from k)
select left(rid::text, 6) r, col, string_agg(case when kind is not null and why is null then '[D] ' when kind is not null then '[K:' || why || '] ' else '' end || s, ' | ' order by ent, k) t
from d group by 1,2 order by 1,2;